using System;using System.IO;using System.Linq;using Musikbox;
class SpeechAudioResults57Tests {static void Main(string[] args){int hits=0,total=0;foreach(string line in File.ReadAllLines(args[0])){var a=line.Split('\t');var song=new Song{Artist=a[0]=="Sunflower"?"Glen Campbell":a[0],Title=a[0]=="Sunflower"?a[0]:"Test",Source="test.mp3"};bool match=LibrarySearch.VoiceMatches(song,a[1]);if(match)hits++;total++;Console.WriteLine((match?"HIT ":"MISS ")+a[0]+" ← "+a[1]);}if(args.Length>1&&hits!=Int32.Parse(args[1]))throw new Exception("Unerwartete Katalogabgleichquote");Console.WriteLine("KATALOGABGLEICH "+hits+"/"+total);byte[] tone=new byte[3200],quiet=new byte[3200];for(int i=0;i<tone.Length;i+=2)tone[i+1]=32;using(var capture=new SpeechCapture()){if(capture.Feed(quiet,quiet.Length)!=null||capture.Finish()!=null)throw new Exception("Stille");for(int i=0;i<3;i++)capture.Feed(tone,tone.Length);byte[] utterance=null;for(int i=0;i<8;i++)utterance=capture.Feed(quiet,quiet.Length);if(utterance==null)throw new Exception("Sprechpause");capture.Feed(tone,tone.Length);capture.Feed(tone,tone.Length);if(capture.Finish()==null||capture.Finish()!=null)throw new Exception("Stop oder Wiederholung");}Console.WriteLine("BESTANDEN: Stille, Sprechpause, Stop und neuer Audiopuffer");}}
